function bin2ascii(array) {
    return String.fromCharCode.apply(null, array);
}

function bin2hex(array, length) {
    length = length || array.length;
    return Array.from(array)
        .slice(0, length)
        .map(byte => ('0' + (byte & 0xFF).toString(16)).slice(-2))
        .join('');
}

Java.perform(function() {
    var SecretKeySpec = Java.use('javax.crypto.spec.SecretKeySpec');
    SecretKeySpec.$init.overload('[B', 'java.lang.String').implementation = function(key, spec) {
        var hexKey = bin2hex(key);
        var asciiKey = bin2ascii(key);
        console.log("KEY: " + hexKey + " | " + asciiKey);
        return this.$init(key, spec);
    };

    var Cipher = Java.use('javax.crypto.Cipher');
    Cipher.getInstance.overload('java.lang.String').implementation = function(spec) {
        console.log("CIPHER: " + spec);
        return this.getInstance(spec);
    };

    Cipher.doFinal.overload('[B').implementation = function(data) {
        console.log("Gotcha!");
        var hexData = bin2hex(data);
        var asciiData = bin2ascii(data);
        console.log("Data: " + hexData + " | " + asciiData);

        var iv = this.getIV();
        if (iv) {
            var hexIV = bin2hex(iv);
            var asciiIV = bin2ascii(iv);
            console.log("IV: " + hexIV + " | " + asciiIV);
        } else {
            console.log("No IV available.");
        }

        return this.doFinal(data);
    };
});
















