// ── 1. FLUTTER TLS BYPASS ────────────────────────────────────────────────────
(function flutterTls() {
  var T = '[tls]';

  // arm64: MOV X0, #0 ; RET  → forces ssl_error_none
  var PATCH = [0x00, 0x00, 0x80, 0xD2,
               0xC0, 0x03, 0x5F, 0xD6];

  // Byte patterns for ssl_verify_peer_cert prologue, arm64, Dart 3.4–3.11 stable
  var PATTERNS = [
    'F3 0F 1E F8 F4 4F 01 A9 FD 7B 02 A9 FD 83 00 91 F3 03 01 AA F4 03 00 AA',
    'F6 57 BD A9 F4 4F 01 A9 FD 7B 02 A9 FD 83 00 91 F3 03 01 AA',
    'FF 83 01 D1 F6 57 03 A9 F4 4F 04 A9 FD 7B 05 A9 FD 43 01 91',
  ];

  function patch(mod) {
    for (var i = 0; i < PATTERNS.length; i++) {
      var hits = Memory.scanSync(mod.base, mod.size, PATTERNS[i]);
      if (hits.length > 0) {
        var addr = hits[0].address;
        Memory.patchCode(addr, PATCH.length, function (code) {
          for (var b = 0; b < PATCH.length; b++) code.add(b).writeU8(PATCH[b]);
        });
        console.log(T + ' patched @ ' + addr + ' (pattern ' + i + ') -> ssl_error_none');
        return;
      }
    }
    console.log(T + ' WARNING: no pattern matched — update patterns for this Dart build');
  }

  var mod = Process.findModuleByName('libflutter.so');
  if (mod) {
    patch(mod);
  } else {
    console.log(T + ' libflutter.so not yet loaded, polling...');
    var iv = setInterval(function () {
      var m = Process.findModuleByName('libflutter.so');
      if (m) { clearInterval(iv); patch(m); }
    }, 500);
  }
})();


// ── 2. CONNECT() REDIRECT ────────────────────────────────────────────────────
(function connectRedirect() {
  var T = '[redir]';

  function findExport(name) {
    return (typeof Module.findGlobalExportByName === 'function')
      ? Module.findGlobalExportByName(name)
      : Module.findExportByName(null, name);
  }

  function ipBytes(ip) {
    return ip.split('.').map(function (o) { return parseInt(o, 10) & 0xff; });
  }

  var pIp = ipBytes(PROXY_IP);
  var ptr = findExport('connect');
  if (!ptr) { console.log(T + ' connect() not found'); return; }

  Interceptor.attach(ptr, {
    onEnter: function (args) {
      try {
        var sa = args[1];
        if (sa.readU16() !== 2) return;                    // AF_INET only
        var port = (sa.add(2).readU8() << 8) | sa.add(3).readU8();
        if (REDIR_PORTS.indexOf(port) === -1) return;
        var orig = sa.add(4).readU8() + '.' + sa.add(5).readU8() + '.'
                 + sa.add(6).readU8() + '.' + sa.add(7).readU8();
        if (orig === PROXY_IP) return;
        sa.add(2).writeU8((PROXY_PORT >> 8) & 0xff);
        sa.add(3).writeU8(PROXY_PORT & 0xff);
        sa.add(4).writeU8(pIp[0]); sa.add(5).writeU8(pIp[1]);
        sa.add(6).writeU8(pIp[2]); sa.add(7).writeU8(pIp[3]);
        console.log(T + ' ' + orig + ':' + port + ' -> ' + PROXY_IP + ':' + PROXY_PORT);
      } catch (_) {}
    }
  });
  console.log(T + ' connect() redirect active -> ' + PROXY_IP + ':' + PROXY_PORT);
})();


