/**
 * Build a java.util.ArrayList from a Frida-wrapped Java array.
 * Arrays.asList() fails on Frida cert chain proxies — iterate manually instead.
 */
function toList(javaArray) {
    const list = Java.use('java.util.ArrayList').$new();
    if (javaArray) {
        for (let i = 0; i < javaArray.length; i++) list.add(javaArray[i]);
    }
    return list;
}

/**
 * Smart trust hook: inspects return type per overload and returns the
 * correct value — List, boolean, or void — without crashing OkHttp.
 */
function hookTrust(className, methodName, label) {
    try {
        Java.use(className)[methodName].overloads.forEach(function(ov) {
            ov.implementation = function() {
                const r = ov.returnType.className;
                if (r === 'java.util.List') return toList(arguments[0]);
                if (r === 'boolean')        return true;
            };
        });
        hooked++;
        ok(label);
    } catch(e) { skip(label); }
}

/** Hook all overloads as void (no-op). */
function hookVoid(className, methodName, label) {
    try {
        Java.use(className)[methodName].overloads.forEach(function(ov) {
            ov.implementation = function() {};
        });
        hooked++;
        ok(label);
    } catch(e) { skip(label); }
}

/** Hook all overloads to return true. */
function hookBool(className, methodName, label) {
    try {
        Java.use(className)[methodName].overloads.forEach(function(ov) {
            ov.implementation = function() { return true; };
        });
        hooked++;
        ok(label);
    } catch(e) { skip(label); }
}

