let flutterHooked = false;

function hookFlutterSSL() {
    const flutter = Process.findModuleByName('libflutter.so');
    if (!flutter) return false;

    const offsets = [0x5dc730, 0x5e5730, 0x5f1730, 0x673740];
    for (const off of offsets) {
        try {
            Interceptor.attach(flutter.base.add(off), {
                onLeave: function(ret) { ret.replace(0x1); }
            });
            hooked++; ok('Flutter SSL @ offset 0x' + off.toString(16));
            flutterHooked = true;
            return true;
        } catch(e) {}
    }

    const patterns = [
        '?? 0F 1C F8 ?? ?? 01 A9 ?? ?? 02 A9 ?? ?? 03 A9 ?? ?? ?? ?? 68 1A 40 F9',
        '?? 43 01 D1 FE 67 01 A9 F8 5F 02 A9 F6 57 03 A9 F4 4F 04 A9 13 00 40 F9 F4 03 00 AA 68 1A 40 F9',
        'FF 43 01 D1 FE 67 01 A9 ?? ?? 06 94 ?? ?? 06 94 68 1A 40 F9 15 15 41 F9 B5 00 00 B4 B6 4A 40 F9',
    ];
    for (const pat of patterns) {
        try {
            const res = Memory.scanSync(flutter.base, flutter.size, pat);
            if (res.length > 0) {
                Interceptor.attach(res[0].address, {
                    onLeave: function(ret) { ret.replace(0x1); }
                });
                hooked++; ok('Flutter SSL via pattern @ +0x' + res[0].address.sub(flutter.base).toString(16));
                flutterHooked = true;
                return true;
            }
        } catch(e) {}
    }

    skip('Flutter SSL — no offset matched (manual offset needed)');
    return false;
}

if (!hookFlutterSSL()) {
    try {
        const watch = (addr) => {
            if (!addr) return;
            Interceptor.attach(addr, {
                onEnter: function(args) { this.path = args[0].readCString(); },
                onLeave: function() {
                    if (this.path && this.path.includes('libflutter.so')) hookFlutterSSL();
                }
            });
        };
        watch(Module.findExportByName(null, 'dlopen'));
        watch(Module.findExportByName(null, 'android_dlopen_ext'));
    } catch(e) {}
}

