            if (fn) {
                Interceptor.attach(fn, {
                    onEnter: function(args) { args[1] = ptr(0); args[2] = ptr(0); }
                });
                hooked++; ok(lib + ' SSL_CTX_set_verify -> VERIFY_NONE');
            }
        }
    } catch(e) {}
}

